practice_sets={
 'Foundations':[
  ('Agentic loops','An agent receives a tool_use stop reason. What should the application do next?',['End the session immediately','Append the tool result and request the next model turn','Ask the user to restart','Ignore the tool call'],'b','The loop continues after tool_use; the tool result becomes the next conversation turn.'),
  ('Tool design','A tool is often mis-selected by the model. What is the best first fix?',['Add a second routing agent','Sharpen the tool description, examples, and boundaries','Increase the temperature','Hide the tool from the model'],'b','Clear purpose, inputs, examples, and boundaries usually improve routing before extra orchestration.'),
  ('Claude Code workflows','Where should shared repository instructions live?',['A private chat message','A personal desktop note','A project-level CLAUDE.md committed with the repository','Only in the CI provider'],'c','Project-level guidance is shareable and versioned with the codebase.'),
  ('Structured output','Extraction fields are inconsistent even though the schema is valid. What should you add?',['Representative few-shot examples','A longer system greeting','More random sampling','A second unrelated tool'],'a','Examples show the intended format and judgment more concretely than prose alone.'),
  ('Context reliability','A long case summary risks losing the refund amount. What protects it best?',['Keep every raw tool response forever','Put key transactional facts in a persistent case-facts block','Ask the model to remember it','Increase temperature'],'b','A compact, explicit facts block preserves high-value details through summarisation.')
 ],
 'Professional':[
  ('Architecture','A service-request assistant can use a workflow, RAG, or an autonomous agent. What should guide the choice?',['The newest model name','Business outcomes, risk, latency, and ownership constraints','The longest prompt','The most autonomous option'],'b','Choose the least complex architecture that meets measured business and risk requirements.'),
  ('Context engineering','How should two model configurations be compared?',['Use one anecdotal prompt','Run representative tasks with quality, latency, and cost measures','Pick the larger context window','Compare marketing claims'],'b','A fair evaluation uses the same representative tasks and explicit success measures.'),
  ('Integration','A RAG assistant can create service tickets. Where should approval happen?',['Only in the prompt','At the service boundary before the consequential write','After the ticket is created','Never'],'b','Authorization and approval belong in deterministic application controls around writes.'),
  ('Evaluation','What belongs in a release evaluation matrix?',['Only average answer length','Quality, groundedness, tool selection, latency, and cost','Only a human thumbs-up','Only token count'],'b','Break results down by task and failure type, using both automated and human checks where needed.'),
  ('Governance','What is the strongest control for confidential documents?',['Trust the model not to disclose them','Enforce access and retention outside the model and audit events','Remove all logging','Use a more cheerful prompt'],'b','Policies must be enforced in the surrounding system, with accountable audit trails.')
 ]
}
for level, questions in practice_sets.items():
 items=[]
 for i,(topic,question,options,answer,explanation) in enumerate(questions,1):
  labels=''.join(f'<label><input type="radio" name="q{i}" value="{chr(97+j)}"> <span>{escape(option)}</span></label>' for j,option in enumerate(options))
  items.append(f'<article class="practice-question" data-answer="{answer}"><p class="eyebrow">ROUND {i:02} · {escape(topic)}</p><h2>{escape(question)}</h2><div class="practice-options">{labels}</div><button class="button practice-check" type="button">Check answer</button><p class="practice-result" role="status" aria-live="polite"></p><p class="practice-explanation">{escape(explanation)}</p></article>')
 page_name=f'claude-architect-{level.lower()}-practice.html'
 page(page_name,f'Claude Architect {level} — Practice',f'''<section class="page-head prep-head"><a class="back-link" href="/certifications.html">← All certification paths</a><p class="eyebrow">LOCAL PRACTICE ROUND · CCAR-{('F' if level=='Foundations' else 'P')}</p><h1>Practice {level}.<br> <em>Think it through.</em></h1><p>Five focused questions built from the study map. Choose an answer, check your reasoning, and use the explanation to guide your next review.</p></section><section class="practice-shell"><div class="practice-banner"><strong>Self-contained study set</strong><span>No account, timer, or external link required.</span></div>{''.join(items)}<div class="study-finish"><p class="eyebrow">KEEP GOING</p><h2>Review the full study map.</h2><p>Return to the {level} preparation path for every domain, task statement, and study action.</p><a class="button" href="/{'claude-architect-foundations' if level=='Foundations' else 'claude-architect-professional'}.html">Back to Learn & prepare ↗</a></div></section>''')

